%==============================================================================
% OrbitLab Automated GMAT Script
% Experiment: BasicTrain001
% Description: Inspect inertial position drift while preparing a lab notebook.
%==============================================================================

%----------------------------------------
%---------- Spacecraft Configuration
%----------------------------------------
Create Spacecraft BasicSat001;

BasicSat001.DateFormat = UTCGregorian;
BasicSat001.Epoch = '01 Jan 2026 12:00:00.000';
BasicSat001.CoordinateSystem = EarthMJ2000Eq;
BasicSat001.DisplayStateType = Keplerian;
BasicSat001.SMA = 7073.000000;
BasicSat001.ECC = 0.004000;
BasicSat001.INC = 13.700000;
BasicSat001.RAAN = 29.000000;
BasicSat001.AOP = 41.000000;
BasicSat001.TA = 53.000000;
BasicSat001.DryMass = 217.00;
BasicSat001.Cd = 2.2000;
BasicSat001.DragArea = 1.0000;
BasicSat001.Cr = 1.8000;
BasicSat001.SRPArea = 1.0000;

%----------------------------------------
%---------- Force Model Configuration
%----------------------------------------
Create ForceModel OrbitLabForceModel;

OrbitLabForceModel.CentralBody = Earth;
OrbitLabForceModel.PrimaryBodies = {Earth};
OrbitLabForceModel.GravityField.Earth.Degree = 4;
OrbitLabForceModel.GravityField.Earth.Order = 4;
OrbitLabForceModel.PointMasses = {Luna, Sun};
OrbitLabForceModel.SRP = On;

%----------------------------------------
%---------- Propagator Configuration
%----------------------------------------
Create Propagator OrbitLabPropagator;
OrbitLabPropagator.FM = OrbitLabForceModel;
OrbitLabPropagator.Type = RungeKutta89;
OrbitLabPropagator.InitialStepSize = 60.00;

%----------------------------------------
%---------- Maneuvers & Impulsive Burns
%----------------------------------------
%----------------------------------------
%---------- Telemetry Subscriber
%----------------------------------------
Create ReportFile OrbitLabReport;
OrbitLabReport.Filename = 'telemetry.txt';
OrbitLabReport.Precision = 8;
OrbitLabReport.WriteHeaders = true;
OrbitLabReport.Add = {BasicSat001.ElapsedSecs, BasicSat001.EarthMJ2000Eq.X, BasicSat001.EarthMJ2000Eq.Y, BasicSat001.EarthMJ2000Eq.Z, BasicSat001.EarthMJ2000Eq.VX, BasicSat001.EarthMJ2000Eq.VY, BasicSat001.EarthMJ2000Eq.VZ, BasicSat001.Earth.SMA, BasicSat001.Earth.ECC, BasicSat001.INC, BasicSat001.Earth.Altitude};

%----------------------------------------
%---------- Mission Sequence
%----------------------------------------
BeginMissionSequence;

Propagate 'Mission Propagation' OrbitLabPropagator(BasicSat001) {BasicSat001.ElapsedDays = 0.5000};

